/**
 * Remove participant's portfolio assignment
 * @summary Remove assignment
 */
export const removeAssignment = (participantId: string) => {
  return customInstance<void>({
    url: `/participant-portfolios/participant/${participantId}`,
    method: "DELETE",
  });
};

export const getRemoveAssignmentMutationOptions = <
  TError = unknown,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof removeAssignment>>,
    TError,
    { participantId: string },
    TContext
  >;
}): UseMutationOptions<
  Awaited<ReturnType<typeof removeAssignment>>,
  TError,
  { participantId: string },
  TContext
> => {
  const mutationKey = ["removeAssignment"];
  const { mutation: mutationOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey } };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof removeAssignment>>,
    { participantId: string }
  > = (props) => {
    const { participantId } = props ?? {};

    return removeAssignment(participantId);
  };

  return { mutationFn, ...mutationOptions };
};

